#!/usr/bin/env python3
import base64, gzip, subprocess
from pathlib import Path

PATCH_B64 = ""

def main():
    app_root = Path(__file__).resolve().parent
    repo_root = app_root.parent
    patch = gzip.decompress(base64.b64decode(PATCH_B64))
    subprocess.run(
        ["git", "-C", str(repo_root), "apply", "--directory=a340-app", "--whitespace=nowarn", "-"],
        input=patch, check=True
    )
    gradle = (app_root / "app/build.gradle.kts").read_text()
    activity = (app_root / "app/src/main/java/com/a340/technicalassistant/LineAssistantActivity.kt").read_text()
    corrector = (app_root / "app/src/main/java/com/a340/technicalassistant/PfrDatabaseOcrCorrector.kt").read_text()
    repo = (app_root / "app/src/main/java/com/a340/technicalassistant/SearchRepository.kt").read_text()
    paths = (app_root / "app/src/main/res/xml/file_paths.xml").read_text()
    assert 'versionCode = 53' in gradle and 'versionName = "1.5.3"' in gradle
    assert 'stageGalleryImage(uri)' in activity
    assert 'ocrDbIo.execute' in activity
    assert 'renderPfrOcrResult(parsed, text, databaseChecked = false)' in activity
    assert 'searchOcrEvidence' in repo and 'repo.searchOcrEvidence' in corrector
    assert 'name="ocr_input"' in paths
    print('Applied LineAssistant 1.5.3 non-blocking photo/OCR pipeline fix')

if __name__ == "__main__":
    main()
